#include <bits/stdc++.h>
using namespace std;

using ll = long long;

constexpr int MOD = 1'000'000'007;
constexpr int LIM = 21;
constexpr int TOTAL = LIM * LIM * LIM * LIM * 2 * 2;

struct Mint {
    int v = 0;

    Mint() = default;
    Mint(ll x) {
        x %= MOD;
        if (x < 0) x += MOD;
        v = static_cast<int>(x);
    }

    Mint& operator+=(const Mint& other) {
        v += other.v;
        if (v >= MOD) v -= MOD;
        return *this;
    }

    friend Mint operator+(Mint a, const Mint& b) {
        return a += b;
    }

    friend Mint operator-(Mint a, const Mint& b) {
        a.v -= b.v;
        if (a.v < 0) a.v += MOD;
        return a;
    }
};

struct State {
    unsigned char a, b, c, d, e, f;
    int id;
};

int getId(int a, int b, int c, int d, int e, int f) {
    return (((((a * LIM + b) * LIM + c) * LIM + d) * 2 + e) * 2 + f);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    ll m;
    cin >> n >> m;

    vector<pair<int, int>> v(n);
    for (auto& [x, y] : v) cin >> x >> y;

    const size_t subsetCount = size_t(1) << n;
    vector<int> addA(subsetCount), addB(subsetCount);
    vector<int> addC(subsetCount), addD(subsetCount);

    for (size_t mask = 1; mask < subsetCount; ++mask) {
        const size_t previous = mask & (mask - 1);
        const int bit = __builtin_ctzll(mask);

        addA[mask] = addA[previous] + max(v[bit].first, 0);
        addB[mask] = addB[previous] + max(-v[bit].first, 0);
        addC[mask] = addC[previous] + max(v[bit].second, 0);
        addD[mask] = addD[previous] + max(-v[bit].second, 0);
    }

    vector<Mint> dp(TOTAL), nextDp(TOTAL);
    vector<int> seen(TOTAL, 0);
    vector<State> active, nextActive;

    const int initialId = getId(0, 0, 0, 0, 0, 0);
    dp[initialId] = Mint(1);
    active.push_back({0, 0, 0, 0, 0, 0, initialId});

    int iteration = 0;

    while (m > 0) {
        ++iteration;
        nextActive.clear();

        for (const State& state : active) {
            const Mint ways = dp[state.id];
            if (ways.v == 0) continue;

            for (size_t mask = 0; mask < subsetCount; ++mask) {
                const int A = state.a + addA[mask];
                const int B = state.b + addB[mask];
                const int C = state.c + addC[mask];
                const int D = state.d + addD[mask];

                if ((A & 1) != (B & 1) || (C & 1) != (D & 1)) continue;

                const int na = A / 2;
                const int nb = B / 2;
                const int nc = C / 2;
                const int nd = D / 2;

                if (na >= LIM || nb >= LIM || nc >= LIM || nd >= LIM) continue;

                int ne = state.e;
                int nf = state.f;

                if ((A & 1) != (m & 1)) ne = (A & 1) > (m & 1);
                if ((C & 1) != (m & 1)) nf = (C & 1) > (m & 1);

                const int id = getId(na, nb, nc, nd, ne, nf);

                if (seen[id] != iteration) {
                    seen[id] = iteration;
                    nextActive.push_back({
                        static_cast<unsigned char>(na),
                        static_cast<unsigned char>(nb),
                        static_cast<unsigned char>(nc),
                        static_cast<unsigned char>(nd),
                        static_cast<unsigned char>(ne),
                        static_cast<unsigned char>(nf),
                        id
                    });
                }

                nextDp[id] += ways;
            }
        }

        for (const State& state : active) dp[state.id] = Mint(0);

        dp.swap(nextDp);
        active.swap(nextActive);
        m /= 2;
    }

    cout << (dp[initialId] - Mint(1)).v << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using ull = unsigned long long;

constexpr int MOD = 1'000'000'007;
constexpr int SHIFT = 6;
constexpr ull MASK = (1ULL << SHIFT) - 1;

struct CustomHash {
    static ull splitmix64(ull x) {
        x += 0x9e3779b97f4a7c15ULL;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
        x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
        return x ^ (x >> 31);
    }

    size_t operator()(ull x) const {
        static const ull seed =
            chrono::steady_clock::now().time_since_epoch().count();
        return splitmix64(x + seed);
    }
};

using HashMap = unordered_map<ull, int, CustomHash>;

ull encode(int a, int b, int c, int d, int e, int f) {
    return static_cast<ull>(a)
         | (static_cast<ull>(b) << SHIFT)
         | (static_cast<ull>(c) << (2 * SHIFT))
         | (static_cast<ull>(d) << (3 * SHIFT))
         | (static_cast<ull>(e) << (4 * SHIFT))
         | (static_cast<ull>(f) << (4 * SHIFT + 1));
}

void add(HashMap& table, ull key, int value) {
    auto [it, inserted] = table.emplace(key, value);
    if (!inserted) {
        it->second += value;
        if (it->second >= MOD) it->second -= MOD;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<pair<int, int>> vectors(n);
    for (auto& [x, y] : vectors) cin >> x >> y;

    HashMap dp;
    dp.max_load_factor(0.7f);
    dp.reserve(1024);
    dp[0] = 1;

    while (m) {
        HashMap current = std::move(dp);

        for (auto [x, y] : vectors) {
            const int da = max(x, 0);
            const int db = max(-x, 0);
            const int dc = max(y, 0);
            const int dd = max(-y, 0);

            const ull delta =
                static_cast<ull>(da)
                | (static_cast<ull>(db) << SHIFT)
                | (static_cast<ull>(dc) << (2 * SHIFT))
                | (static_cast<ull>(dd) << (3 * SHIFT));

            vector<pair<ull, int>> existing;
            existing.reserve(current.size());
            for (const auto& [key, value] : current) {
                existing.emplace_back(key, value);
            }

            current.reserve(current.size() * 2 + 1);
            for (const auto& [key, value] : existing) {
                add(current, key + delta, value);
            }
        }

        HashMap next;
        next.max_load_factor(0.7f);
        next.reserve(current.size());

        for (const auto& [key, value] : current) {
            const int a = key & MASK;
            const int b = (key >> SHIFT) & MASK;
            const int c = (key >> (2 * SHIFT)) & MASK;
            const int d = (key >> (3 * SHIFT)) & MASK;
            int e = (key >> (4 * SHIFT)) & 1;
            int f = (key >> (4 * SHIFT + 1)) & 1;

            if ((a & 1) != (b & 1) || (c & 1) != (d & 1)) continue;

            if ((a & 1) != (m & 1)) e = (a & 1) > (m & 1);
            if ((c & 1) != (m & 1)) f = (c & 1) > (m & 1);

            add(next, encode(a / 2, b / 2, c / 2, d / 2, e, f), value);
        }

        dp = std::move(next);
        m /= 2;
    }

    int answer = 0;
    auto it = dp.find(0);
    if (it != dp.end()) answer = it->second;

    answer = (answer - 1 + MOD) % MOD;
    cout << answer << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

constexpr int MOD = 1'000'000'007;
constexpr int LIM = 21;
constexpr int STATES = LIM * LIM * LIM * LIM * 2 * 2;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<pair<int, int>> v(n);
    for (auto &[x, y] : v) cin >> x >> y;

    const int subsetCount = 1 << n;
    vector<int> addA(subsetCount), addB(subsetCount);
    vector<int> addC(subsetCount), addD(subsetCount);

    for (int mask = 1; mask < subsetCount; ++mask) {
        int bit = __builtin_ctz(mask);
        int prev = mask & (mask - 1);

        addA[mask] = addA[prev] + max(v[bit].first, 0);
        addB[mask] = addB[prev] + max(-v[bit].first, 0);
        addC[mask] = addC[prev] + max(v[bit].second, 0);
        addD[mask] = addD[prev] + max(-v[bit].second, 0);
    }

    auto encode = [](int a, int b, int c, int d, int e, int f) {
        int id = a;
        id = id * LIM + b;
        id = id * LIM + c;
        id = id * LIM + d;
        id = id * 2 + e;
        id = id * 2 + f;
        return id;
    };

    vector<int> dp(STATES), nextDp(STATES);
    vector<unsigned char> touched(STATES);
    vector<int> active{0}, nextActive;

    dp[0] = 1;

    while (m > 0) {
        nextActive.clear();

        for (int id : active) {
            int value = dp[id];
            if (value == 0) continue;

            int state = id;
            int f = state % 2;
            state /= 2;
            int e = state % 2;
            state /= 2;
            int d = state % LIM;
            state /= LIM;
            int c = state % LIM;
            state /= LIM;
            int b = state % LIM;
            state /= LIM;
            int a = state;

            for (int mask = 0; mask < subsetCount; ++mask) {
                int A = a + addA[mask];
                int B = b + addB[mask];
                int C = c + addC[mask];
                int D = d + addD[mask];

                if ((A & 1) != (B & 1) || (C & 1) != (D & 1))
                    continue;

                int E = e;
                int F = f;

                if ((A & 1) != (m & 1))
                    E = (A & 1) > (m & 1);
                if ((C & 1) != (m & 1))
                    F = (C & 1) > (m & 1);

                int na = A / 2;
                int nb = B / 2;
                int nc = C / 2;
                int nd = D / 2;

                if (na >= LIM || nb >= LIM || nc >= LIM || nd >= LIM)
                    continue;

                int nextId = encode(na, nb, nc, nd, E, F);

                if (!touched[nextId]) {
                    touched[nextId] = 1;
                    nextActive.push_back(nextId);
                }

                nextDp[nextId] += value;
                if (nextDp[nextId] >= MOD)
                    nextDp[nextId] -= MOD;
            }
        }

        for (int id : active)
            dp[id] = 0;
        for (int id : nextActive)
            touched[id] = 0;

        dp.swap(nextDp);
        active.swap(nextActive);
        m /= 2;
    }

    cout << (dp[0] - 1 + MOD) % MOD << '\n';
    return 0;
}

